import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry);
      setResult(entry);
    } catch { setError('Kunde inte analysera just nu. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{ setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="default" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 28px 52px', maxWidth:480, margin:'0 auto', display:'flex', flexDirection:'column', alignItems:'center', gap:0 }}>

        {/* Editorial heading */}
        <div style={{ width:'100%', marginBottom:40, animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
          {streak > 0 && (
            <div style={{ display:'inline-flex', alignItems:'center', gap:7, padding:'4px 12px', borderRadius:100, background:'rgba(0,0,0,0.06)', border:'1px solid rgba(0,0,0,0.08)', marginBottom:20, fontSize:11, color:'rgba(26,26,30,0.55)', fontFamily:'DM Mono,monospace', letterSpacing:'0.08em' }}>
              🔥 {streak} dag{streak>1?'ar':''} i rad
            </div>
          )}
          <h1 style={{ fontSize:'clamp(44px,10vw,72px)', fontWeight:700, letterSpacing:'-0.055em', lineHeight:0.86, color:'#1a1a1e' }}>
            BRYT<br/>
            <span style={{ color:'rgba(26,26,30,0.22)' }}>TANKE-<br/>SPIRALEN</span>
          </h1>
        </div>

        {/* Orb — centered, full size, visible */}
        <div style={{ marginBottom:40, animation:'fadeIn .8s .1s ease both', position:'relative' }}>
          <Orb3D size={300} variant="dark" speed={0.4} />
          <div style={{ position:'absolute', bottom:8, left:'50%', transform:'translateX(-50%)', background:'rgba(255,255,255,0.6)', backdropFilter:'blur(12px)', border:'1px solid rgba(0,0,0,0.08)', borderRadius:100, padding:'4px 14px', whiteSpace:'nowrap' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', color:'rgba(26,26,30,0.5)', textTransform:'uppercase' }}>Mental health · KBT</span>
          </div>
        </div>

        {/* Input */}
        <div style={{ width:'100%', animation:'fadeUp .8s .2s cubic-bezier(0.16,1,0.3,1) both' }}>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:10 }}>
            <div style={{ width:5, height:5, borderRadius:'50%', background:'rgba(26,26,36,0.4)', animation:'pulse 2.5s infinite' }} />
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(26,26,30,0.4)' }}>Vad snurrar i huvudet?</span>
          </div>
          <div className="glass" style={{ borderRadius:20, padding:'20px 22px', marginBottom:10 }}>
            <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
              placeholder="Skriv fritt..."
              style={{ width:'100%', minHeight:100, background:'transparent', border:'none', color:'#1a1a1e', fontSize:15, fontWeight:300, lineHeight:1.75, resize:'none', outline:'none' }}
            />
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', paddingTop:12, borderTop:'1px solid rgba(0,0,0,0.06)' }}>
              <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(26,26,30,0.25)' }}>{text.length}/1000</span>
              <button onClick={handleSubmit} disabled={!text.trim()||loading}
                style={{ padding:'9px 20px', borderRadius:100, fontSize:12, fontWeight:600, transition:'all .25s', background: text.trim()&&!loading ? '#1a1a24' : 'rgba(0,0,0,0.1)', color: text.trim()&&!loading ? '#fff' : 'rgba(26,26,36,0.3)', border:'none' }}>
                {loading
                  ? <span style={{ display:'flex',alignItems:'center',gap:8 }}><span style={{ width:10,height:10,border:'2px solid rgba(255,255,255,0.3)',borderTopColor:'#fff',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar...</span>
                  : 'Analysera →'}
              </button>
            </div>
            {error && <p style={{ color:'rgba(180,50,50,0.8)', fontSize:12, marginTop:10 }}>{error}</p>}
          </div>

          {/* Quick nav */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
            {[
              { id:'checkin',   icon:'✅', label:'Check-in',   sub:'Hur mår du?' },
              { id:'breathing', icon:'🫁', label:'Andning',    sub:'4-7-8 teknik' },
            ].map(({ id, icon, label, sub }) => (
              <button key={id} onClick={()=>setPage(id)} className="glass"
                style={{ padding:'14px 16px', borderRadius:16, display:'flex', alignItems:'center', gap:10, color:'rgba(26,26,30,0.6)', fontSize:13, transition:'all .2s', textAlign:'left' }}
                onMouseEnter={e=>{e.currentTarget.style.color='#1a1a24';e.currentTarget.style.background='rgba(255,255,255,0.55)'}}
                onMouseLeave={e=>{e.currentTarget.style.color='rgba(26,26,36,0.6)';e.currentTarget.style.background='rgba(255,255,255,0.35)'}}>
                <span style={{ fontSize:18 }}>{icon}</span>
                <div>
                  <div style={{ fontSize:12, fontWeight:500, color:'#1a1a1e' }}>{label}</div>
                  <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(26,26,30,0.35)', marginTop:1 }}>{sub}</div>
                </div>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="warm" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 28px 60px', maxWidth:480, margin:'0 auto', animation:'fadeUp .6s cubic-bezier(0.16,1,0.3,1) both' }}>

        <div style={{ display:'flex', justifyContent:'center', marginBottom:36 }}>
          <Orb3D size={200} variant="dusk" speed={0.3} />
        </div>

        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(26,26,30,0.35)', marginBottom:8 }}>{result.trap_icon} Tankefälla</p>
        <h2 style={{ fontSize:'clamp(32px,7vw,52px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#1a1a1e', marginBottom:28 }}>{result.trap_label}</h2>

        <div style={{ borderLeft:'2px solid rgba(0,0,0,0.12)', paddingLeft:16, marginBottom:28, fontSize:13, color:'rgba(26,26,30,0.4)', fontStyle:'italic', lineHeight:1.7 }}>"{text.slice(0,120)}{text.length>120?'...':''}"</div>

        {[
          { label:'Vad händer', body:result.description },
          { label:'Omramning',  body:result.reframe },
          { label:'Övning',     body:result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ marginBottom:16 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(26,26,30,0.35)', marginBottom:7 }}>{label}</p>
            <div className="glass" style={{ borderRadius:16, padding:'16px 18px' }}>
              <p style={{ fontSize:14, color:'rgba(26,26,30,0.8)', lineHeight:1.85, fontWeight:300 }}>{body}</p>
            </div>
          </div>
        ))}

        {result.second_trap && result.second_trap !== 'null' && (
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(26,26,30,0.28)', marginBottom:20 }}>Möjlig sekundär: {result.second_trap}</p>
        )}

        <div style={{ display:'flex', gap:10, marginTop:12 }}>
          <button onClick={()=>setPage('breathing')} className="glass"
            style={{ flex:1, padding:'13px', borderRadius:14, color:'rgba(26,26,30,0.6)', fontSize:13, transition:'all .2s' }}
            onMouseEnter={e=>e.currentTarget.style.color='#1a1a24'} onMouseLeave={e=>e.currentTarget.style.color='rgba(26,26,36,0.6)'}>
            🫁 Andningsövning
          </button>
          <button onClick={onBack} style={{ padding:'13px 20px', borderRadius:14, color:'rgba(26,26,30,0.35)', fontSize:13 }}>← Tillbaka</button>
        </div>
      </div>
    </div>
  );
}
